import {initializeGuide} from './guide.mjs';
import {retrieve,classify,validate,simulate,procedure} from './engine.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let corpus,report,plan=null,last=null;
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function notice(title,text,tone=''){return `<div class="notice ${tone}"><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;}
function evidence(c){const d=corpus.documents.find(d=>d.id===c.document);return `<div class="evidencecard"><span class="score">${c.score==null?'':c.score.toFixed(2)+' score'}</span><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p><a href="${esc(d.url+(c.page?'#page='+c.page:''))}" target="_blank" rel="noopener">${esc(d.title)}</a><div class="meta">${esc(c.locator)} · ${esc(d.version)}<br>Editorial paraphrase · evidence ID: ${esc(c.id)}</div></div>`;}
function analyze(){const q=$('#request').value.trim();plan=null;last=null;$('#run').disabled=true;$('#exportplan').disabled=true;$('#exportcode').disabled=true;$('#simresult').innerHTML='';$('#validation').innerHTML='';if(!q){$('#analysis').innerHTML=notice('Enter a request','Describe a test or measurement question.','warn');$('#results').innerHTML='';return;}const c=classify(q);$('#analysis').innerHTML=notice(c.family==='idss'?'Candidate: IDSS drain leakage':c.family==='ambiguous'?'Clarification needed':c.family==='unknown'?'Evidence search only':'Candidate: '+c.family.toUpperCase(),c.reason,c.family==='idss'?'':'warn');const hits=retrieve(q,corpus,$('#mode').value);$('#results').innerHTML=hits.length?hits.map(evidence).join(''):notice('No evidence found','Try a measurement term such as IDSS, guarding, settling, or gate leakage.','warn');}
function readPlan(){const fd=new FormData($('#planform'));return Object.fromEntries([...fd.entries()].map(([k,v])=>[k,k==='connections'?true:v]));}
function validatePlan(e){e?.preventDefault();const p=readPlan();const family=classify($('#request').value).family;const errors=validate(p);if(family!=='idss')errors.unshift({field:'request',message:'Procedure generation requires a single explicit IDSS / drain-leakage request.'});plan=null;last=null;$('#simresult').innerHTML='';$('#run').disabled=true;$('#exportplan').disabled=true;$('#exportcode').disabled=true;if(errors.length){$('#validation').innerHTML=`<div class="notice error"><h3>${errors.length} item${errors.length===1?'':'s'} to resolve</h3><ul>${errors.map(e=>`<li><strong>${esc(e.field)}</strong>: ${esc(e.message)}</li>`).join('')}</ul></div>`;return;}plan={...p,connections:true};$('#run').disabled=false;$('#exportplan').disabled=false;$('#exportcode').disabled=false;const match=Number(p.vds)===48&&Number(p.limit)===1;$('#validation').innerHTML=notice('Plan validated for simulation',match?'The 48 V, zero-gate, 25°C, 1 µA comparison matches the selected datasheet condition. Compliance, delay, and sample count remain user-approved simulation settings.':'Custom bias or acceptance limit selected. This is not a datasheet conformance test; the selected threshold is user supplied.',match?'':'warn')+`<details><summary>Inspect the structured plan</summary><pre>${esc(JSON.stringify({...plan,scope:'simulation only',source:'vishay#page=2',limit_origin:match?'datasheet condition':'user-supplied custom limit'},null,2))}</pre></details>`;}
function chart(rows,limit){const w=560,h=160,pad=22,max=Math.max(limit*1.3,...rows.map(r=>r.current_uA))*1.15;const x=i=>pad+i*(w-pad*2)/Math.max(1,rows.length-1),y=v=>h-pad-v/max*(h-pad*2);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Synthetic current trace in microamperes; dashed line is the acceptance limit"><line x1="${pad}" y1="${y(limit)}" x2="${w-pad}" y2="${y(limit)}" stroke="#c14843" stroke-dasharray="5 4"/><text x="${pad}" y="${Math.max(14,y(limit)-5)}" fill="#a23a35" font-size="12">limit ${limit} µA</text><polyline points="${rows.map((r,i)=>x(i)+','+y(r.current_uA)).join(' ')}" fill="none" stroke="#0b7667" stroke-width="2"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.current_uA)}" r="3" fill="#0b7667"/>`).join('')}</svg>`;}
function run(){if(!plan)return;try{last=simulate(plan,$('#scenario').value);$('#simresult').innerHTML=`<div class="runstatus ${last.status==='PASS'?'pass':'fail'}">${esc(last.status)}</div><p class="muted">Mean ${last.mean_uA.toFixed(3)} µA · ${last.rows.length} samples · seed 42</p>${chart(last.rows,Number(plan.limit))}<p class="tiny">${esc(last.model)} ${esc(last.comparison)}</p>${last.scenario==='fixture'?notice('A failure does not identify its cause','This scenario adds fixture current. The comparator cannot distinguish fixture contamination from a defective device.','warn'):''}<details><summary>Instrument command trace</summary><pre>${esc(last.trace.join('\n'))}</pre></details><button id="exportreadings">Download readings CSV</button>`;$('#exportreadings').onclick=()=>download('testbridge-readings.csv','sample,time_s,current_uA,compliance\n'+last.rows.map(r=>[r.sample,r.time_s,r.current_uA,r.compliance].join(',')).join('\n'),'text/csv');}catch(e){$('#simresult').innerHTML=notice('Run blocked',e.message,'error');}}
function renderKnowledge(){const q=$('#kbsearch').value.toLowerCase();$('#kb').innerHTML=corpus.chunks.filter(c=>(c.title+' '+c.text+' '+c.tags).toLowerCase().includes(q)).map(c=>`<article>${evidence(c)}</article>`).join('')||notice('No matching records','Try a broader measurement term.');}
function renderEval(){const pct=n=>(n*100).toFixed(1)+'%';$('#metrics').innerHTML=`<div class="statgrid"><div class="stat"><strong>${report.queries}</strong><span>Synthetic queries · ${report.groups} paraphrase groups</span></div><div class="stat"><strong>+${(report.paired_delta.estimate*100).toFixed(1)} pp</strong><span>Recall@3 versus BM25 · development set</span></div><div class="stat"><strong>${(report.paired_delta.ci95[0]*100).toFixed(1)}–${(report.paired_delta.ci95[1]*100).toFixed(1)} pp</strong><span>95% cluster-bootstrap interval</span></div></div><article><div class="tablewrap"><table><thead><tr><th>Method</th><th>Recall@3</th><th>MRR@3</th></tr></thead><tbody>${report.methods.map(m=>`<tr><td>${m.method==='hybrid'?'BM25 + terminology expansion':m.method==='bm25'?'BM25 baseline':'Keyword overlap'}</td><td>${pct(m.recall_at_3)}</td><td>${m.mrr_at_3.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Recall@3: proportion of queries whose labeled evidence appears in the first three results. MRR@3: reciprocal rank of the first relevant result, with zero outside the first three.</p>${notice('Development benchmark only','The same author created the evidence labels and terminology map. The 100% expanded-retrieval result is not evidence of generalization to unseen engineer requests.','warn')}<p class="tiny">${esc(report.paired_delta.method)}. No neural embeddings or learned reranker are used.</p><a href="evaluation.json" download>Download complete results</a> · <a href="benchmark.json" download>Download benchmark</a></article>`;
$('#benchmark').innerHTML=`<article><h3>Inspect every query and its result</h3><label for="benchmode">Method to inspect</label><select id="benchmode"><option value="bm25">BM25 baseline</option><option value="keyword">Keyword overlap</option><option value="hybrid">BM25 + terminology expansion</option></select><div class="tablewrap" id="benchrows"></div></article>`;const rows=()=>{const m=report.methods.find(m=>m.method===$('#benchmode').value);$('#benchrows').innerHTML=`<table><thead><tr><th>Query / group</th><th>Expected</th><th>Retrieved IDs</th><th>Hit</th></tr></thead><tbody>${m.rows.map(r=>`<tr><td>${esc(r.query)}<div class="tiny">${r.group}</div></td><td>${r.relevant.map(esc).join(', ')}</td><td>${r.hits.map(esc).join(', ')}</td><td>${r.recall?'✓':'Miss'}</td></tr>`).join('')}</tbody></table>`;};$('#benchmode').onchange=rows;rows();}
try{[corpus,report]=await Promise.all(['corpus.json','evaluation.json'].map(async f=>{const r=await fetch(f);if(!r.ok)throw new Error('Could not load '+f);return r.json();}));$('#analyze').onclick=analyze;$('#mode').onchange=analyze;document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('#request').value=b.dataset.example;analyze();});$('#request').oninput=()=>{plan=null;$('#run').disabled=true;$('#exportplan').disabled=true;$('#exportcode').disabled=true;$('#validation').innerHTML='';$('#simresult').innerHTML='';};$('#preset').onclick=()=>{const p={device:'2N7000',vds:48,vgs:0,temperature:25,limit:1,compliance:100,settling:1,samples:20};for(const [k,v]of Object.entries(p))$('#planform').elements[k].value=v;$('#planform').elements.connections.checked=false;$('#provenance').innerHTML='<p>VDS, VGS, temperature, and limit: Vishay datasheet p. 2. Compliance 100 µA, delay 1 s, and 20 samples: illustrative simulation choices, not source-prescribed settings.</p>';plan=null;$('#run').disabled=true;$('#exportplan').disabled=true;$('#exportcode').disabled=true;$('#validation').innerHTML='';$('#simresult').innerHTML='';};$('#planform').onsubmit=validatePlan;$('#planform').oninput=()=>{plan=null;$('#run').disabled=true;$('#exportplan').disabled=true;$('#exportcode').disabled=true;$('#validation').innerHTML='';$('#simresult').innerHTML='';};$('#run').onclick=run;$('#exportplan').onclick=()=>plan&&download('testbridge-plan.json',JSON.stringify({...plan,scope:'simulation only'},null,2));$('#exportcode').onclick=()=>plan&&download('testbridge-procedure.py',procedure(plan),'text/x-python');$('#kbsearch').oninput=renderKnowledge;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==b.dataset.view));});analyze();renderKnowledge();renderEval();initializeGuide(corpus,{renderEvidence:evidence,escape:esc,openWorkbench:()=>{const detail=document.querySelector('#technical-details');detail.open=true;detail.scrollIntoView({behavior:'smooth',block:'start'});}});
 const context=document.modelContext;if(context?.registerTool){const life=new AbortController();for(const tool of [{name:'analyze_test_request',description:'Set the visible engineering request and retrieve evidence. Clears any prior validated plan.',inputSchema:{type:'object',properties:{request:{type:'string',minLength:1}},required:['request'],additionalProperties:false},execute(input){if(typeof input?.request!=='string'||!input.request.trim())throw new Error('Nonempty request required');$('#request').value=input.request;analyze();return {classification:classify(input.request),evidence:retrieve(input.request,corpus,$('#mode').value).map(c=>({id:c.id,locator:c.locator}))};}},{name:'read_testbridge_plan',description:'Read the current validated simulation plan without modifying it.',annotations:{readOnlyHint:true},inputSchema:{type:'object',properties:{},additionalProperties:false},execute(){return {plan,last_run:last?{status:last.status,mean_uA:last.mean_uA}:null};}}]){try{await context.registerTool(tool,{signal:life.signal});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
}catch(e){$('#analysis').innerHTML=notice('Workbench could not load',e.message,'error');}
